// Package gateway builds the REST/JSON HTTP handler for this service. It is
// generated by grpc-gateway from the google.api.http options on
// GaragesGatewayService (see internal/grpc/proto/garages/v1/garages_gateway.proto),
// so this service transcodes REST <-> gRPC itself instead of relying on an
// external plugin.
package gateway

import (
	"context"
	"encoding/json"
	"fmt"
	"net"
	"net/http"
	"strings"
	"time"

	"github.com/grpc-ecosystem/grpc-gateway/v2/runtime"
	"google.golang.org/grpc"
	"google.golang.org/grpc/codes"
	"google.golang.org/grpc/credentials/insecure"
	"google.golang.org/grpc/keepalive"
	"google.golang.org/grpc/status"
	"google.golang.org/protobuf/encoding/protojson"

	pb "github.com/autofik-development/autofik.dev.api.garages.getway/internal/grpc/pb/garages/v1"
)

// DefaultGRPCPort is the gRPC listen port used when GRPC_LISTEN_ADDR is unset.
const DefaultGRPCPort = "50057"

// errorResponse matches the {status, message, code} envelope the rest of the
// platform returns. grpc-gateway's default error body is
// {"code":2,"message":...,"details":[]}, which does not match that contract
// and exposes the numeric gRPC code as if it were an application code.
type errorResponse struct {
	Status  string `json:"status"`
	Message string `json:"message"`
	Code    string `json:"code"`
}

// NewHandler dials grpcAddr - this process's own gRPC listener - and returns
// an http.Handler that forwards REST/JSON requests as real gRPC calls, plus
// a closer for the dialed connection. Routing back in as an actual gRPC call
// (rather than calling the server implementation directly) is what keeps
// requests flowing through the server's UnaryInterceptor chain.
//
// The marshaler uses UseProtoNames so JSON keys stay the exact proto field
// names with no camelCase conversion, and EmitUnpopulated so every response
// keeps a stable shape: proto3 JSON otherwise drops zero values, so a
// garage's `"is_verified": false` or `"experience_years": null` would vanish.
func NewHandler(ctx context.Context, grpcAddr string) (http.Handler, func() error, error) {
	mux := runtime.NewServeMux(
		runtime.WithMarshalerOption(runtime.MIMEWildcard, &runtime.JSONPb{
			MarshalOptions: protojson.MarshalOptions{
				UseProtoNames:   true,
				EmitUnpopulated: true,
			},
			UnmarshalOptions: protojson.UnmarshalOptions{
				DiscardUnknown: true,
			},
		}),
		runtime.WithErrorHandler(errorHandler),
		runtime.WithIncomingHeaderMatcher(incomingHeaderMatcher),
	)

	conn, err := grpc.NewClient(grpcAddr,
		// The dial target is this process's own loopback listener, so plain
		// text here never leaves the pod. Inbound TLS belongs on the
		// external listeners, not on this hop.
		grpc.WithTransportCredentials(insecure.NewCredentials()),
		grpc.WithKeepaliveParams(keepalive.ClientParameters{
			Time:                30 * time.Second,
			Timeout:             10 * time.Second,
			PermitWithoutStream: true,
		}),
		grpc.WithDefaultCallOptions(
			grpc.MaxCallRecvMsgSize(MaxMessageSize),
			grpc.MaxCallSendMsgSize(MaxMessageSize),
		),
	)
	if err != nil {
		return nil, nil, fmt.Errorf("gateway: dial grpc endpoint %s: %w", grpcAddr, err)
	}

	if err := pb.RegisterGaragesGatewayServiceHandler(ctx, mux, conn); err != nil {
		conn.Close()
		return nil, nil, fmt.Errorf("gateway: register handler: %w", err)
	}

	return mux, conn.Close, nil
}

// NewMux mounts the probe endpoints ahead of the grpc-gateway handler.
// "/healty" is the platform's historical (misspelled) probe path, kept so the
// same probes work against every gateway; /healthz and /readyz are the
// conventional spellings.
func NewMux(grpcGateway http.Handler) *http.ServeMux {
	mux := http.NewServeMux()
	mux.HandleFunc("/healty", HealthyHandler)
	mux.HandleFunc("/healthz", HealthyHandler)
	mux.HandleFunc("/readyz", ReadyHandler)
	mux.Handle("/", grpcGateway)
	return mux
}

// MaxMessageSize bounds a single gRPC message on the loopback hop.
const MaxMessageSize = 8 << 20 // 8 MiB

// errorHandler renders a gRPC status as the platform's JSON error envelope.
func errorHandler(ctx context.Context, mux *runtime.ServeMux, marshaler runtime.Marshaler, w http.ResponseWriter, r *http.Request, err error) {
	st := status.Convert(err)

	w.Header().Del("Trailer")
	w.Header().Del("Transfer-Encoding")
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(runtime.HTTPStatusFromCode(st.Code()))

	_ = json.NewEncoder(w).Encode(errorResponse{
		Status:  "error",
		Message: st.Message(),
		Code:    errorCode(st.Code()),
	})
}

// errorCode turns a gRPC code into the SCREAMING_SNAKE string the platform's
// clients already branch on.
func errorCode(code codes.Code) string {
	switch code {
	case codes.InvalidArgument:
		return "INVALID_ARGUMENT"
	case codes.Unauthenticated:
		return "UNAUTHENTICATED"
	case codes.PermissionDenied:
		return "PERMISSION_DENIED"
	case codes.NotFound:
		return "NOT_FOUND"
	case codes.AlreadyExists:
		return "ALREADY_EXISTS"
	case codes.ResourceExhausted:
		return "RESOURCE_EXHAUSTED"
	case codes.DeadlineExceeded:
		return "DEADLINE_EXCEEDED"
	case codes.Unavailable:
		return "SERVICE_UNAVAILABLE"
	case codes.Unimplemented:
		return "NOT_IMPLEMENTED"
	case codes.Canceled:
		return "REQUEST_CANCELLED"
	default:
		return "INTERNAL_ERROR"
	}
}

// incomingHeaderMatcher forwards the headers the handlers and logs need.
// runtime.DefaultHeaderMatcher already passes Authorization through as
// "authorization"; this adds the correlation and client-IP headers an edge
// proxy sets, which the default matcher would drop.
func incomingHeaderMatcher(key string) (string, bool) {
	switch strings.ToLower(key) {
	case "x-request-id", "x-correlation-id", "x-forwarded-for", "x-real-ip":
		return strings.ToLower(key), true
	default:
		return runtime.DefaultHeaderMatcher(key)
	}
}

// LoopbackTarget turns a gRPC listen address (e.g. ":50057" or
// "0.0.0.0:50057") into a target this process can dial to reach its own
// server.
func LoopbackTarget(listenAddr string) string {
	_, port, err := net.SplitHostPort(listenAddr)
	if err != nil || port == "" {
		port = DefaultGRPCPort
	}
	return net.JoinHostPort("127.0.0.1", port)
}
